82	    /**
83	     * Dedicated audit logger. On a successful create an audit line carrying the new owner's id,
84	     * {@code memberId}, {@code registrationDate} and {@code membershipLevel} is emitted to the
85	     * logger named {@code AUDIT}.
86	     */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    /**
90	     * Monotonically increasing sequence number stamped onto each structured {@link OwnerCreatedEvent}.
91	     * Shared across all creates so the events carry a total order independent of the owner id.
92	     */
93	    private static final AtomicLong AUDIT_SEQUENCE = new AtomicLong();
94	
95	    /**
96	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
97	     * at least one dot and no whitespace on either side.
98	     */
99	    private static final Pattern EMAIL_PATTERN =
100	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
101	
102	    /**
103	     * Disposable email domains that an owner's email may not use. An email whose domain (the part
104	     * after the {@code @}, compared case-insensitively) is on this list is rejected with a 400
105	     * response naming {@code email}.
106	     */
107	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
108	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
109	
110	    /**
111	     * Common street-type abbreviations expanded during address normalization. Keys are the
112	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
113	     * expanded form.
114	     */
115	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
116	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
117	
118	    /**
119	     * Required national-number length per E.164 country code (the digits that follow the country
120	     * code). {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
121	     * A country code that is not listed here is not length-checked, keeping other numbers accepted.
122	     */
123	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH =
124	        Map.of("1", 10, "61", 9);
125	
126	    /**
127	     * Inclusive 4-digit postcode range allowed for each known region, keyed by the region an owner's
128	     * city derives to (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD): NSW 2000-2099, VIC
129	     * 3000-3099, QLD 4000-4099. A city that derives to no known region ({@code "UNKNOWN"}) is not in
130	     * this table and accepts any 4-digit postcode.
131	     */
132	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
133	        "NSW", new int[] {2000, 2099},
134	        "VIC", new int[] {3000, 3099},
135	        "QLD", new int[] {4000, 4099});
