137	    /**
138	     * The maximum number of owners a single city may contain. A create request for a city that
139	     * already holds this many owners is rejected with a 409 response.
140	     */
141	    private static final int MAX_OWNERS_PER_CITY = 50;
142	
143	    /**
144	     * The number of owners a city must already contain for a create in that city to be flagged as
145	     * approaching capacity. When an existing city holds at least this many owners but fewer than
146	     * {@value #MAX_OWNERS_PER_CITY} (so the create is still accepted), the new owner is created with
147	     * {@code capacityWarning} set to {@code true}.
148	     */
149	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
150	
151	    /**
152	     * The maximum number of owners that may be registered in a single day. A create request made
153	     * once this many owners already carry today's {@code registrationDate} is rejected with a 429
154	     * response.
155	     */
156	    private static final int MAX_OWNERS_PER_DAY = 100;
157	
158	    /**
159	     * The number of owners that must already carry a day's {@code registrationDate} before a create
160	     * for that day is flagged as a bulk signup. Once more than this many owners already exist for the
161	     * day, the new owner is created with {@code bulkSignupWarning} set to {@code true}.
162	     */
163	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
164	
165	    /**
166	     * The tenure, in elapsed fiscal years, an owner must exceed to reach {@code membershipLevel} 4.
167	     * Tenure accrues from membership, so a newly created owner (zero tenure) never clears this
168	     * threshold and is therefore capped at level 3 on create.
169	     */
170	    private static final int TENURE_LEVEL_THRESHOLD_FISCAL_YEARS = 1;
171	
172	    /**
173	     * The HTTP header carrying a client-supplied idempotency token for owner creation. When a create
174	     * request repeats with a token already seen, the originally created owner is returned instead of
175	     * a second owner being created.
176	     */
177	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
