228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
231	        String idempotencyKey = idempotencyKey();
232	        if (idempotencyKey != null) {
233	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
234	            if (existingId != null) {
235	                Owner existing = this.clinicService.findOwnerById(existingId);
236	                if (existing != null) {
237	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
238	                }
239	            }
240	        }
241	        normalizeAddress(ownerFieldsDto);
242	        validateRequiredFields(ownerFieldsDto);
243	        normalizeTelephone(ownerFieldsDto);
244	        normalizeEmail(ownerFieldsDto);
245	        validatePostcode(ownerFieldsDto);
246	        String householdId = computeHouseholdId(ownerFieldsDto);
247	        rejectDuplicate(ownerFieldsDto);
248	        rejectCityAtCapacity(ownerFieldsDto);
249	        resolveRegistrationDate(ownerFieldsDto);
250	        rejectDailyLimitReached(ownerFieldsDto.getRegistrationDate());
251	        HttpHeaders headers = new HttpHeaders();
252	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
253	        owner.setHouseholdId(householdId);
254	        assignMemberId(owner);
255	        assignNamesakeCount(owner);
256	        assignBulkSignupWarning(owner);
257	        assignCapacityWarning(owner);
258	        assignPossibleDuplicate(owner, ownerFieldsDto);
259	        assignHouseholdMembership(owner);
260	        assignMembership(owner);
261	        this.clinicService.saveOwner(owner);
262	        if (idempotencyKey != null) {
263	            this.idempotentCreates.put(idempotencyKey, owner.getId());
264	        }
265	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
266	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
267	        emitOwnerCreatedEvent(owner);
268	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
269	        headers.setLocation(UriComponentsBuilder.newInstance()
270	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
271	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
272	    }
