274	    /**
275	     * Emits the immutable structured {@link OwnerCreatedEvent} for a just-persisted owner to the
276	     * {@code AUDIT} logger as a JSON object, alongside the human-readable audit line. Each event is
277	     * stamped with the next value of {@link #AUDIT_SEQUENCE} (monotonically increasing across creates)
278	     * and carries the owner's current primary identifier via {@link #primaryIdentifier}.
279	     */
280	    private void emitOwnerCreatedEvent(Owner owner) {
281	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQUENCE.incrementAndGet(), owner.getId(),
282	            primaryIdentifier(owner), owner.getMembershipLevel());
283	        AUDIT.info(event.toJson());
284	    }
