393	    /**
394	     * Returns the trimmed {@code Idempotency-Key} header of the current request, or {@code null} when
395	     * the header is absent, blank or there is no active request. A present key opts a create into the
396	     * idempotent-repeat behaviour tracked by {@link #idempotentCreates}.
397	     */
398	    private String idempotencyKey() {
399	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
400	            return null;
401	        }
402	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
403	        if (key == null || key.trim().isEmpty()) {
404	            return null;
405	        }
406	        return key.trim();
407	    }
