410	        List<String> missingFields = new ArrayList<>();
411	        if (isBlank(ownerFieldsDto.getFirstName())) {
412	            missingFields.add("firstName");
413	        }
414	        if (isBlank(ownerFieldsDto.getLastName())) {
415	            missingFields.add("lastName");
416	        }
417	        if (isBlank(ownerFieldsDto.getAddress())) {
418	            missingFields.add("address");
419	        }
420	        if (isBlank(ownerFieldsDto.getCity())) {
421	            missingFields.add("city");
422	        }
423	        if (isBlank(ownerFieldsDto.getTelephone())) {
424	            missingFields.add("telephone");
425	        }
426	        if (!missingFields.isEmpty()) {
427	            throw new InvalidOwnerFieldsException(missingFields);
