435	    /**
436	     * Normalizes an owner's address on create, supporting both the structured form
437	     * ({@code addressLine1} plus optional {@code addressLine2}) and the flat {@code address} form kept
438	     * for backward compatibility. Whichever fields are supplied are canonicalized in place - trimmed,
439	     * internal whitespace runs collapsed to a single space, upper-cased and common street-type
440	     * abbreviations expanded as whole tokens ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
441	     * {@code AVE}->{@code AVENUE}). The canonical {@code addressLine1}/{@code addressLine2} are written
442	     * back, and the composed {@code address} - the normalized {@code addressLine1} with a single space
443	     * and the normalized {@code addressLine2} appended when present, falling back to the normalized
444	     * flat {@code address} when no structured line is given - is written onto the request so it is what
445	     * gets validated, compared, stored and returned. Running before the required-field check means an
446	     * address that is blank in both forms after normalization is rejected like a missing one.
447	     */
448	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
449	        String line1 = canonicalAddress(ownerFieldsDto.getAddressLine1());
450	        String line2 = canonicalAddress(ownerFieldsDto.getAddressLine2());
451	        String flat = canonicalAddress(ownerFieldsDto.getAddress());
452	        ownerFieldsDto.setAddressLine1(line1);
453	        ownerFieldsDto.setAddressLine2(line2);
454	        ownerFieldsDto.setAddress(composeAddress(line1, line2, flat));
455	    }
456	
457	    /**
458	     * Composes the effective address, preferring the structured form: when {@code line1} is present
459	     * (non-blank) the result is {@code line1}, with a single space and {@code line2} appended when
460	     * {@code line2} is present; otherwise the flat {@code address} is used. All three inputs are
461	     * expected to be already canonicalized. Returns the flat value (which may be {@code null} or blank,
462	     * left for the required-field check to reject) when no structured line is supplied.
463	     */
464	    private static String composeAddress(String line1, String line2, String flat) {
465	        if (line1 != null && !line1.isBlank()) {
466	            if (line2 != null && !line2.isBlank()) {
467	                return line1 + " " + line2;
468	            }
469	            return line1;
470	        }
471	        return flat;
472	    }
473	
474	    /**
475	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
476	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
477	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
478	     * address is returned unchanged, making it safe to apply to stored values during comparison.
479	     */
480	    private static String canonicalAddress(String address) {
481	        if (address == null) {
482	            return null;
483	        }
484	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
485	        if (collapsed.isEmpty()) {
486	            return "";
487	        }
488	        String[] tokens = collapsed.split(" ");
489	        StringBuilder sb = new StringBuilder(collapsed.length());
490	        for (int i = 0; i < tokens.length; i++) {
491	            if (i > 0) {
492	                sb.append(' ');
493	            }
494	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
495	        }
496	        return sb.toString();
497	    }
