499	    /**
500	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
501	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
502	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
503	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
504	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
505	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
506	     * written back onto the request so it is what gets stored and returned. Any value that cannot
507	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
508	     * {@code telephone}.
509	     */
510	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
511	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
512	    }
513	
514	    /**
515	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
516	     * (400) naming {@code telephone} when it cannot form a valid number.
517	     */
518	    private static String toE164(String telephone) {
519	        if (telephone == null) {
520	            throw new InvalidOwnerFieldsException(List.of("telephone"));
521	        }
522	        boolean hasCountryCode = telephone.trim().startsWith("+");
523	        String digits = telephone.replaceAll("\\D", "");
524	        String countryCode;
525	        String national;
526	        if (hasCountryCode) {
527	            countryCode = matchCountryCode(digits);
528	            national = digits;
529	        } else {
530	            countryCode = "61";
531	            if (digits.startsWith("0")) {
532	                digits = digits.substring(1);
533	            }
534	            national = "61" + digits;
535	        }
536	        if (!national.matches("[0-9]{8,15}")) {
537	            throw new InvalidOwnerFieldsException(List.of("telephone"));
538	        }
539	        if (countryCode != null) {
540	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
541	            if (requiredLength != null
542	                && national.length() - countryCode.length() != requiredLength) {
543	                throw new InvalidOwnerFieldsException(List.of("telephone"));
544	            }
545	        }
546	        return "+" + national;
547	    }
