549	    /**
550	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
551	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
552	     * the number is not length-checked against a country.
553	     */
554	    private static String matchCountryCode(String digits) {
555	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
556	            .filter(digits::startsWith)
557	            .max(Comparator.comparingInt(String::length))
558	            .orElse(null);
559	    }
