561	    /**
562	     * Rejects creating an owner that duplicates an existing one on the derived {@code identityKey} -
563	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
564	     * soundex(lastName)} (see {@link IdentityKey}). An exact key match means the same telephone, email
565	     * and same-sounding surname, i.e. the same person re-registering; because the telephone is part of
566	     * the key, two people who merely share a surname (and postcode) but carry different telephones no
567	     * longer collide here - they are surfaced as a soft match instead (see
568	     * {@link #assignPossibleDuplicate}). This single identity key is the only hard-duplicate rule; the
569	     * computed {@code householdId} no longer contributes a separate 409. A match is a 409.
570	     *
571	     * <p>Owners flagged {@code deleted} (soft-deleted via {@code DELETE /api/owners/{id}}) are skipped
572	     * entirely, so a normally-blocking duplicate is allowed when the only matching owner has been
573	     * deleted.
574	     *
575	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block. The incoming telephone
576	     * and email have already been normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}
577	     * (the email-domain blocklist applies first, in {@link #normalizeEmail}); each existing owner's key
578	     * is derived the same way before comparison. A match results in a 409 response naming
579	     * {@code identityKey}.
580	     */
581	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto) {
582	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
583	            return;
584	        }
585	        String identityKey = IdentityKey.of(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(),
586	            ownerFieldsDto.getLastName());
587	        for (Owner existing : this.clinicService.findAllOwners()) {
588	            if (Boolean.TRUE.equals(existing.getDeleted())) {
589	                continue;
590	            }
591	            if (identityKey.equals(existingIdentityKey(existing))) {
592	                throw new DuplicateOwnerIdentityException(identityKey);
593	            }
594	        }
595	    }
