661	    /**
662	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
663	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
664	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
665	     */
666	    private static String normalizeForComparison(String value) {
