673	    /**
674	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
675	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
676	     * written back onto the request so that is what gets stored and returned. A present but invalid
677	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
678	     */
679	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
680	        String email = ownerFieldsDto.getEmail();
681	        if (email == null) {
682	            return;
683	        }
684	        String trimmed = email.trim();
685	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
686	            throw new InvalidOwnerFieldsException(List.of("email"));
687	        }
688	        String normalized = trimmed.toLowerCase(Locale.ROOT);
689	        String domain = normalized.substring(normalized.indexOf('@') + 1);
690	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
691	            throw new InvalidOwnerFieldsException(List.of("email"));
