696	    /**
697	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
698	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
699	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
700	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
701	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
702	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
703	     * as-is so it is stored and returned.
704	     */
705	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
706	        String postcode = ownerFieldsDto.getPostcode();
707	        if (postcode == null) {
708	            return;
709	        }
710	        if (!postcode.matches("[0-9]{4}")) {
711	            throw new InvalidOwnerFieldsException(List.of("postcode"));
712	        }
713	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
714	        if (range != null) {
715	            int value = Integer.parseInt(postcode);
716	            if (value < range[0] || value > range[1]) {
717	                throw new InvalidOwnerFieldsException(List.of("postcode"));
718	            }
