722	    /**
723	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
724	     * day. When the caller supplies no value it defaults to the server's current date; a value
725	     * provided in the request is kept. A supplied value later than the server's current date is
726	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
727	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
728	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
729	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
730	     * every value derived from the registration date is based on.
731	     */
732	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
733	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
734	        if (effective == null) {
735	            effective = LocalDate.now();
736	        }
737	        else if (effective.isAfter(LocalDate.now())) {
738	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
739	        }
740	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
741	    }
