743	    /**
744	     * The fixed public-holiday calendar. A registration date landing on one of these days is rolled
745	     * forward, just like a weekend, until it reaches a non-holiday business day.
746	     */
747	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
748	        LocalDate.of(2026, 1, 1),
749	        LocalDate.of(2026, 1, 26),
750	        LocalDate.of(2026, 4, 25),
751	        LocalDate.of(2026, 12, 25),
752	        LocalDate.of(2026, 12, 28));
753	
754	    /**
755	     * Rolls a date forward onto a business day: a Saturday, Sunday or listed public holiday is
756	     * advanced one day at a time until it reaches the next non-holiday business day; a weekday that
757	     * is not a holiday is returned unchanged.
758	     */
759	    private static LocalDate toBusinessDay(LocalDate date) {
760	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
761	            date = date.plusDays(1);
762	        }
763	        return date;
764	    }
765	
766	    /**
767	     * Returns whether the given date falls on a Saturday or Sunday.
768	     */
769	    private static boolean isWeekend(LocalDate date) {
770	        return switch (date.getDayOfWeek()) {
771	            case SATURDAY, SUNDAY -> true;
772	            default -> false;
773	        };
774	    }
