776	    /**
777	     * Assigns the owner's unified {@code memberId} on create, formatted
778	     * {@code '<REGION><FY><HASH8><CHK>'} where {@code REGION} is the region the owner's identity
779	     * derives to from its postcode (falling back to the city table when the postcode is absent or in
780	     * no known range), {@code FY} is the two-digit fiscal year of the business-day-adjusted
781	     * {@code registrationDate} (the fiscal year starts on 1 July, e.g. a registration on 2026-08-03
782	     * falls in fiscal year 2027 and yields {@code '27'}), {@code HASH8} is the first eight upper-case
783	     * hex characters of the SHA-256 digest of the normalized telephone concatenated with the last
784	     * name, and {@code CHK} is a single Luhn check digit over the digits of the
785	     * {@code '<REGION><FY><HASH8>'} body (e.g. {@code 'NSW271A2B3C4D4'}). The telephone has already
786	     * been normalized to E.164 form by {@link #normalizeTelephone} and {@code registrationDate} has
787	     * been defaulted, so both inputs are present. The identity is a pure function of region, fiscal
788	     * year, telephone and last name; the check digit is computed over the body before any
789	     * collision-handling suffix is applied.
790	     */
791	    private void assignMemberId(Owner owner) {
792	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
793	        String fy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
794	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
795	        String body = region + fy + hash8;
796	        int chk = MemberIdCheckDigit.of(body);
797	        owner.setMemberId(deduplicateMemberId(body + chk));
798	    }
