800	    /**
801	     * Returns {@code memberId} unchanged when no existing owner already carries it; otherwise appends
802	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by any
803	     * existing owner. Compared against the pre-existing owners, so the returned member id is unique
804	     * among them.
805	     */
806	    private String deduplicateMemberId(String memberId) {
807	        Set<String> existing = new HashSet<>();
808	        for (Owner owner : this.clinicService.findAllOwners()) {
809	            if (owner.getMemberId() != null) {
810	                existing.add(owner.getMemberId());
811	            }
812	        }
813	        if (!existing.contains(memberId)) {
814	            return memberId;
815	        }
816	        int n = 2;
817	        while (existing.contains(memberId + "-" + n)) {
818	            n++;
819	        }
820	        return memberId + "-" + n;
821	    }
