829	        String firstName = owner.getFirstName();
830	        String lastName = owner.getLastName();
831	        int count = 0;
832	        for (Owner existing : this.clinicService.findAllOwners()) {
833	            if (firstName.equalsIgnoreCase(existing.getFirstName())
834	                && lastName.equalsIgnoreCase(existing.getLastName())) {
