841	    /**
842	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
843	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
844	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
845	     * {@value #TENURE_LEVEL_THRESHOLD_FISCAL_YEARS} elapsed fiscal year. The points are then mapped to a level of 1 (0-1
846	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
847	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
848	     * tenure, so the tenure bonus never applies on create.
849	     */
850	    private void assignMembership(Owner owner) {
851	        int points = 0;
852	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
853	            points += 2;
854	        }
855	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
856	            points += 1;
857	        }
858	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
859	            points += 2;
860	        }
861	        if (tenureFiscalYears(owner) > TENURE_LEVEL_THRESHOLD_FISCAL_YEARS) {
862	            points += 3;
863	        }
864	        owner.setMembershipPoints(points);
865	        owner.setMembershipLevel(capMembershipLevelByHousehold(owner, membershipLevelForPoints(points)));
866	    }
