868	    /**
869	     * Caps a newly derived {@code membershipLevel} so it cannot exceed one above the current maximum
870	     * {@code membershipLevel} among the new owner's existing household members - the pre-existing owners
871	     * already carrying the same {@code householdId}. When the owner belongs to no household, or has no
872	     * existing household member, no cap applies and the derived level is returned unchanged. Runs after
873	     * {@link #assignHouseholdMembership} so the owner's {@code householdId} is settled.
874	     */
875	    private int capMembershipLevelByHousehold(Owner owner, int derivedLevel) {
876	        String householdId = owner.getHouseholdId();
877	        if (householdId == null || householdId.isBlank()) {
878	            return derivedLevel;
879	        }
880	        Integer maxHouseholdLevel = null;
881	        for (Owner existing : this.clinicService.findAllOwners()) {
882	            if (householdId.equals(existing.getHouseholdId()) && existing.getMembershipLevel() != null
883	                && (maxHouseholdLevel == null || existing.getMembershipLevel() > maxHouseholdLevel)) {
884	                maxHouseholdLevel = existing.getMembershipLevel();
885	            }
886	        }
887	        if (maxHouseholdLevel == null) {
888	            return derivedLevel;
889	        }
890	        return Math.min(derivedLevel, maxHouseholdLevel + 1);
891	    }
