893	    /**
894	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
895	     * 4-5, and 4 for 6 or more points.
896	     */
897	    private int membershipLevelForPoints(int points) {
898	        if (points <= 1) {
899	            return 1;
900	        }
901	        if (points <= 3) {
902	            return 2;
903	        }
904	        if (points <= 5) {
905	            return 3;
906	        }
907	        return 4;
908	    }
