961	     * {@code postcode} (a present, exact match) yet a <em>different</em> {@code identityKey} - the
962	     * soft-match now keys on the surname sound and postcode rather than an exact last name, and fires
963	     * precisely for the near-miss the identity key lets through (same household surname and postcode
964	     * but a different telephone, so a different key). When such an owner exists,
965	     * {@code possibleDuplicate} is set to {@code true} and {@code possibleDuplicateOf} to that owner's
966	     * id (the lowest id when several match); otherwise {@code possibleDuplicate} is {@code false} and
967	     * {@code possibleDuplicateOf} is left {@code null}. Computed before the new owner is persisted, so
968	     * it considers only the pre-existing owners.
969	     *
970	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
971	     * has deliberately opted into an existing household, so its shared last name and postcode are
972	     * expected rather than a suspected duplicate.
973	     */
974	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
975	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
976	            owner.setPossibleDuplicate(false);
977	            owner.setPossibleDuplicateOf(null);
978	            return;
979	        }
980	        String postcode = owner.getPostcode();
981	        String soundex = IdentityKey.soundex(owner.getLastName());
982	        String identityKey = IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
983	        Integer matchId = null;
984	        if (postcode != null && !postcode.isBlank()) {
985	            for (Owner existing : this.clinicService.findAllOwners()) {
986	                if (soundex.equals(IdentityKey.soundex(existing.getLastName()))
987	                    && postcode.equals(existing.getPostcode())
988	                    && !identityKey.equals(existingIdentityKey(existing))
989	                    && existing.getId() != null
990	                    && (matchId == null || existing.getId() < matchId)) {
991	                    matchId = existing.getId();
992	                }
993	            }
994	        }
