1019	    /**
1020	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
1021	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
1022	     * every existing owner already carrying the same identifier. Runs after the owner's
1023	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
1024	     * Left {@code null} when the owner belongs to no household.
1025	     */
1026	    private void assignHouseholdMembership(Owner owner) {
1027	        String householdId = owner.getHouseholdId();
1028	        if (householdId == null || householdId.isBlank()) {
1029	            owner.setHouseholdMemberCount(null);
1030	            return;
1031	        }
1032	        int count = 1;
1033	        for (Owner existing : this.clinicService.findAllOwners()) {
1034	            if (householdId.equals(existing.getHouseholdId())) {
1035	                count++;
1036	            }
1037	        }
1038	        owner.setHouseholdMemberCount(count);
1039	    }
1040	
1041	    /**
1042	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
1043	     * upper-case hexadecimal. Used to derive the {@code memberId} HASH8 segment and the household
1044	     * identifier, both stable functions of their inputs.
1045	     */
1046	    private static String shaHexUpper(String input, int length) {
1047	        try {
1048	            byte[] digest = MessageDigest.getInstance("SHA-256")
1049	                .digest(input.getBytes(StandardCharsets.UTF_8));
1050	            StringBuilder hex = new StringBuilder(digest.length * 2);
1051	            for (byte b : digest) {
1052	                hex.append(String.format("%02x", b));
1053	            }
1054	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
1055	        } catch (NoSuchAlgorithmException ex) {
1056	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
1057	        }
1058	    }
